import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores: agent_id -> float, higher = more cooperative
        self.reputation = {}
        # Track interactions with each agent: agent_id -> {'c': count, 'd': count}
        self.interactions = {}
        # Partner-specific cooperation rates
        self.partner_coop_rates = {}
        # Global cooperation rate
        self.global_coop_rate = 0.5
        self.total_observations = 0
        self.total_coops_observed = 0
        # Personal recent behavior to detect own mistakes
        self.my_recent_actions = []
        # Track if we've been exploited (their defection vs our cooperation)
        self.exploited_count = 0
        self.exploited_by = set()
        # Cooperation threshold for reputation
        self.coop_threshold = 0.5
        # Memory window for recent interactions
        self.recent_window = 20
        self.recent_interactions = {}
        # Whether to be adaptive (can be tuned)
        self.adaptation_factor = 0.05

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Default to cooperate if unknown
        if opponent not in self.reputation:
            return True
        rep = self.reputation[opponent]
        # If opponent has good reputation, cooperate; else defect
        # Add slight randomness to avoid predictability
        if rep > self.coop_threshold:
            return random.random() < (0.95 + 0.05 * rep)
        else:
            return random.random() < 0.1

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global stats
        self.total_observations += 1
        if donor_action == 'cooperate':
            self.total_coops_observed += 1
        if recipient_action == 'cooperate':
            self.total_coops_observed += 1
        self.global_coop_rate = self.total_coops_observed / (2 * self.total_observations)

        # Update reputation for both agents based on their action
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue  # Don't judge ourselves
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0.5
            # Update reputation: cooperation increases, defection decreases
            if action == 'cooperate':
                self.reputation[agent_id] += self.adaptation_factor * (1.0 - self.reputation[agent_id])
            else:
                self.reputation[agent_id] -= self.adaptation_factor * (self.reputation[agent_id] - 0.0)
            # Clamp
            self.reputation[agent_id] = max(0.0, min(1.0, self.reputation[agent_id]))

        # Update interaction counts (only for our own interactions or if we're observing, track all)
        # Track for each agent the counts
        if donor_id not in self.interactions:
            self.interactions[donor_id] = {'c': 0, 'd': 0}
        if recipient_id not in self.interactions:
            self.interactions[recipient_id] = {'c': 0, 'd': 0}
        self.interactions[donor_id][donor_action[0]] += 1
        self.interactions[recipient_id][recipient_action[0]] += 1

        # Update recent interactions for own interactions (or for others, but keep limited)
        # For self-judgment, we track our own behavior and the other's response
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            # Record in recent window
            if other_id not in self.recent_interactions:
                self.recent_interactions[other_id] = []
            self.recent_interactions[other_id].append((my_action, other_action))
            if len(self.recent_interactions[other_id]) > self.recent_window:
                self.recent_interactions[other_id].pop(0)

            # Update partner cooperation rate based on their action
            if other_id not in self.partner_coop_rates:
                self.partner_coop_rates[other_id] = 0.5
            # Smooth update
            self.partner_coop_rates[other_id] = self.partner_coop_rates[other_id] * 0.9 + (1.0 if other_action == 'cooperate' else 0.0) * 0.1

            # Track exploitation: if I cooperated and they defected
            if my_action == 'cooperate' and other_action == 'defect':
                self.exploited_count += 1
                self.exploited_by.add(other_id)
            # If they cooperated and I defected, we might be the exploiter – adjust reputation of self? We don't judge self, so just note.

        # Also track third-party observed interactions with small weight
        else:
            # We can update reputation of donors/recipients as above, already done
            # Additionally, we can update partner_coop_rates for observed partners with lower weight
            # But we already update reputation for all, so fine.
            pass

        # Occasionally adjust threshold based on global cooperation
        if self.total_observations % 50 == 0:
            # If global cooperation is low, be less trusting
            self.coop_threshold = 0.5 - 0.2 * (self.global_coop_rate - 0.5)
            # Also adjust adaptation factor slightly
            self.adaptation_factor = min(0.1, 0.02 + 0.02 * self.global_coop_rate)

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round = 0
        self.gen = 0
        self.my_scores = {}
        self.reputation = {}
        self.generosity = 0.5
        self.trust = {}
        self.last_opponent = None
        self.last_action = None
        self.last_result = None
        self.observed = {}
        self.interactions = {}
        self.total_rounds = 30
        self.total_gens = 30
        self.memory = []
        self.coop_count = 0
        self.defect_count = 0
        self.opponent_history = {}
        self.self_history = []
        self.gen_start = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent
        if self.round < 2:
            # Start cooperative
            self.last_action = True
            return True

        # Estimate opponent cooperation probability
        opp_coop_prob = 0.5
        if opponent in self.opponent_history:
            hist = self.opponent_history[opponent]
            if len(hist) > 0:
                opp_coop_prob = sum(1 for a in hist if a) / len(hist)

        # My own reputation (how often I've cooperated)
        my_coop_rate = 0.5
        if len(self.self_history) > 0:
            my_coop_rate = sum(1 for a in self.self_history if a) / len(self.self_history)

        # Trust factor based on opponent's history
        trust_factor = 1.0
        if opponent in self.trust:
            trust_factor = self.trust[opponent]

        # Generosity parameter adjusts based on outcomes
        # If I've been exploited, become less generous
        if self.last_result == "exploited":
            self.generosity = max(0.1, self.generosity - 0.05)
        elif self.last_result == "cooperated":
            self.generosity = min(0.9, self.generosity + 0.02)

        # Adaptive strategy: cooperate with probability based on opponent and reputation
        coop_prob = 0.5 + 0.3 * (opp_coop_prob - 0.5) + 0.2 * (my_coop_rate - 0.5) + 0.1 * trust_factor
        coop_prob = max(0.1, min(0.9, coop_prob))

        # Use generosity to slightly favor cooperation
        coop_prob = coop_prob * (1 - self.generosity) + self.generosity * 0.5

        # Deterministic threshold based on round number and generation
        noise = 0.02 * math.sin(self.gen * 3.7 + self.round * 1.3 + self.agent_id)
        action = (coop_prob + noise) > 0.5

        self.last_action = action
        return action

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update round counters based on self observations
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # This is a self-judgment
            if donor_id == self.agent_id:
                self.last_result = "cooperated" if donor_action == "cooperate" else "defected"
            else:
                self.last_result = "cooperated" if recipient_action == "cooperate" else "defected"

            # Record my action
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            self.self_history.append(my_action == "cooperate")
            if my_action == "cooperate":
                self.coop_count += 1
            else:
                self.defect_count += 1

            # Update opponent history for my last opponent
            if self.last_opponent is not None:
                if self.last_opponent not in self.opponent_history:
                    self.opponent_history[self.last_opponent] = []
                # The opponent's action in this interaction
                if donor_id == self.agent_id:
                    opp_action = recipient_action
                else:
                    opp_action = donor_action
                self.opponent_history[self.last_opponent].append(opp_action == "cooperate")

                # Update trust based on outcome
                if self.last_result == "cooperated" and opp_action == "cooperate":
                    # Mutual cooperation increases trust
                    self.trust[self.last_opponent] = self.trust.get(self.last_opponent, 0) + 0.1
                elif self.last_result == "exploited":
                    self.trust[self.last_opponent] = self.trust.get(self.last_opponent, 0) - 0.15
                elif self.last_result == "defected":
                    self.trust[self.last_opponent] = self.trust.get(self.last_opponent, 0) - 0.05

        # Third-party observation: update reputation of both agents
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Track cooperation rate of each agent
            if donor_id not in self.reputation:
                self.reputation[donor_id] = [0, 0]  # [coop_count, total]
            if recipient_id not in self.reputation:
                self.reputation[recipient_id] = [0, 0]

            self.reputation[donor_id][1] += 1
            self.reputation[recipient_id][1] += 1
            if donor_action == "cooperate":
                self.reputation[donor_id][0] += 1
            if recipient_action == "cooperate":
                self.reputation[recipient_id][0] += 1

        # Track interactions for analysis
        key = (min(donor_id, recipient_id), max(donor_id, recipient_id))
        if key not in self.interactions:
            self.interactions[key] = []
        self.interactions[key].append((donor_action, recipient_action))

        # Increment round counter when a self observation occurs
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round += 1
            if self.round >= self.total_rounds:
                self.round = 0
                self.gen += 1
                # Reset trust slowly each generation
                for opp in self.trust:
                    self.trust[opp] *= 0.9
                # Reset per-generation history? Keep overall but decay
                if self.gen >= self.total_gens:
                    # End of simulation, no action needed
                    pass

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each agent, a score that increases with observed cooperation
        # and decreases with observed defection. Also track number of interactions.
        self.reputation = {}
        self.interaction_count = {}
        # Track direct experiences: for each opponent, count of cooperative/defective actions by them
        self.direct_coop = {}
        self.direct_defect = {}
        # Track my own actions to adjust against specific opponents
        self.my_coop_vs = {}
        self.my_defect_vs = {}
        # Forgiving/grudging threshold: how much reputation is needed to trust
        self.trust_threshold = 0.0  # slightly positive
        # Adaptive threshold based on overall population cooperation
        self.avg_reputation = 0.0
        self.num_obs = 0
        # Exploration: small chance to defect occasionally to test
        self.explore_prob = 0.05

    def _update_reputation(self, agent_id: int, action: str, weight: float = 1.0) -> None:
        if action == "cooperate":
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.0) + weight
        else:
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.0) - weight

    def decide(self) -> bool:
        opponent = getattr(self, "_ctx_opponent_id", None)
        if opponent is None:
            # No opponent? Default to cooperate
            return True
        # Exploration
        if random.random() < self.explore_prob:
            return random.choice([True, False])
        # Calculate trust score based on reputation and direct experience
        rep = self.reputation.get(opponent, 0.0)
        # Direct experience: if we've seen them cooperate more, increase trust
        direct_diff = self.direct_coop.get(opponent, 0) - self.direct_defect.get(opponent, 0)
        trust = rep + direct_diff
        # If opponent has never interacted, default to cooperative but cautious
        if opponent not in self.interaction_count and opponent not in self.reputation:
            trust = 0.0
        return trust >= self.trust_threshold

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for both donor and recipient based on their actions
        # The recipient's action is also observed (they chose simultaneously)
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)
        self.interaction_count[donor_id] = self.interaction_count.get(donor_id, 0) + 1
        self.interaction_count[recipient_id] = self.interaction_count.get(recipient_id, 0) + 1

        # Track direct experiences if I'm involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent
            if donor_id == self.agent_id:
                opponent = recipient_id
                my_action = donor_action
                their_action = recipient_action
            else:
                opponent = donor_id
                my_action = recipient_action
                their_action = donor_action
            # Update my direct counts
            if my_action == "cooperate":
                self.my_coop_vs[opponent] = self.my_coop_vs.get(opponent, 0) + 1
            else:
                self.my_defect_vs[opponent] = self.my_defect_vs.get(opponent, 0) + 1
            if their_action == "cooperate":
                self.direct_coop[opponent] = self.direct_coop.get(opponent, 0) + 1
            else:
                self.direct_defect[opponent] = self.direct_defect.get(opponent, 0) + 1

        # Update population average reputation (simple moving average)
        self.num_obs += 1
        total_rep = sum(self.reputation.values())
        if self.reputation:
            self.avg_reputation = total_rep / len(self.reputation)
        # Adjust trust threshold based on average reputation: if population is cooperative, be more trusting
        self.trust_threshold = -0.1 * self.avg_reputation  # negative correlation: higher avg -> lower threshold
        # Clamp threshold to a reasonable range
        self.trust_threshold = max(-1.0, min(1.0, self.trust_threshold))

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each other agent, store count of cooperative and defective actions observed
        self.coop_count = {}
        self.defect_count = {}
        # Track cooperation rate of self and others
        self.my_coop = 0
        self.my_defect = 0
        # Track how many times we've seen each agent
        self.obs_count = {}
        # Memory of recent interactions we were part of
        self.my_history = []
        # Strategy parameters
        self.generosity = 0.1
        self.forgiveness = 0.15
        self.threshold = 0.5  # base cooperation threshold

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # If we haven't seen opponent, default to cooperate
        if opponent not in self.coop_count and opponent not in self.defect_count:
            return True

        coop = self.coop_count.get(opponent, 0)
        defect = self.defect_count.get(opponent, 0)
        total = coop + defect
        if total == 0:
            return True

        # Opponent's cooperation rate
        opp_coop_rate = coop / total

        # Adjust based on my own recent behavior: if I've been cooperating a lot, be more forgiving
        my_total = self.my_coop + self.my_defect
        if my_total > 0:
            my_coop_rate = self.my_coop / my_total
            # If I cooperate a lot, be slightly more generous
            adjusted = opp_coop_rate + self.generosity * my_coop_rate
        else:
            adjusted = opp_coop_rate

        # Add forgiveness: if opponent has cooperated recently (last few observations), boost
        # Simple: if recent observations show cooperation, boost threshold
        # We'll track a simple recency: use a small buffer of last 10 observations per opponent
        # For simplicity, just use overall rate plus a small bias if they cooperated last time we saw them
        # We'll store last action observed for each opponent
        if hasattr(self, 'last_action'):
            if opponent in self.last_action:
                if self.last_action[opponent] == 'cooperate':
                    adjusted += self.forgiveness
                else:
                    adjusted -= self.forgiveness * 0.5

        # Decide: cooperate if adjusted rate >= threshold
        # Add slight randomness to avoid being too predictable
        if adjusted >= self.threshold:
            return True
        else:
            # Sometimes still cooperate with low probability to explore
            return random.random() < 0.05

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update counts for donor
        self._update_counts(donor_id, donor_action)
        # Update counts for recipient
        self._update_counts(recipient_id, recipient_action)

        # If I'm involved, update my own history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine my action and opponent action
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            # Update my counts
            if my_action == 'cooperate':
                self.my_coop += 1
            else:
                self.my_defect += 1

            # Store in history (keep last 10)
            self.my_history.append((opp_id, my_action, opp_action))
            if len(self.my_history) > 10:
                self.my_history.pop(0)

            # Track last action for this opponent
            if not hasattr(self, 'last_action'):
                self.last_action = {}
            self.last_action[opp_id] = opp_action

        # For third-party observations, also track last action seen for that agent
        if not hasattr(self, 'last_action'):
            self.last_action = {}
        # Update last action for donor and recipient if we observed them
        self.last_action[donor_id] = donor_action
        self.last_action[recipient_id] = recipient_action

    def _update_counts(self, agent_id: int, action: str) -> None:
        if action == 'cooperate':
            self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
        else:
            self.defect_count[agent_id] = self.defect_count.get(agent_id, 0) + 1
        self.obs_count[agent_id] = self.obs_count.get(agent_id, 0) + 1

