from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_history = {}
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.my_recent_actions = []
        self.generosity = 0.6
        self.contrition = 0.3
        self.forget_factor = 0.9
        self._ctx_opponent_id = None

    def _get_reputation_score(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            return 0.5
        obs = self.reputation[agent_id]
        if len(obs) == 0:
            return 0.5
        total = 0.0
        weight_sum = 0.0
        for i, coop in enumerate(obs):
            weight = math.pow(self.forget_factor, i)
            total += weight * (1.0 if coop else 0.0)
            weight_sum += weight
        return total / weight_sum if weight_sum > 0 else 0.5

    def _record_observation(self, agent_id: int, action: str) -> None:
        coop = (action == 'cooperate')
        if agent_id not in self.reputation:
            self.reputation[agent_id] = deque(maxlen=10)
        self.reputation[agent_id].appendleft(coop)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        rep = self._get_reputation_score(opponent)
        hist = self.interaction_history.get(opponent, [])
        if len(hist) == 0:
            threshold = self.generosity
        else:
            last_my, last_their = hist[-1]
            if last_their:
                threshold = 0.85
            else:
                threshold = 0.3 + 0.2 * rep
            if len(self.my_recent_actions) > 0 and not self.my_recent_actions[-1]:
                threshold = min(1.0, threshold + self.contrition)
        return random.random() < threshold

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self._record_observation(donor_id, donor_action)
        self._record_observation(recipient_id, recipient_action)
        if donor_id == self.agent_id:
            self.my_recent_actions.append(donor_action == 'cooperate')
            if len(self.my_recent_actions) > 5:
                self.my_recent_actions.pop(0)
            if recipient_id not in self.interaction_history:
                self.interaction_history[recipient_id] = []
            self.interaction_history[recipient_id].append((donor_action == 'cooperate', recipient_action == 'cooperate'))
            if donor_action == 'cooperate':
                self.my_coop_count += 1
            else:
                self.my_defect_count += 1
        elif recipient_id == self.agent_id:
            self.my_recent_actions.append(recipient_action == 'cooperate')
            if len(self.my_recent_actions) > 5:
                self.my_recent_actions.pop(0)
            if donor_id not in self.interaction_history:
                self.interaction_history[donor_id] = []
            self.interaction_history[donor_id].append((recipient_action == 'cooperate', donor_action == 'cooperate'))
            if recipient_action == 'cooperate':
                self.my_coop_count += 1
            else:
                self.my_defect_count += 1
        total = self.my_coop_count + self.my_defect_count
        if total > 10:
            coop_ratio = self.my_coop_count / total
            target = max(0.3, min(0.8, 0.5 + (0.5 - coop_ratio) * 0.2))
            self.generosity = self.generosity * self.forget_factor + target * (1 - self.forget_factor)
        if len(self.my_recent_actions) > 0:
            last_action = self.my_recent_actions[-1]
            if last_action:
                self.contrition = max(0.1, self.contrition - 0.05)
            else:
                self.contrition = min(0.6, self.contrition + 0.05)

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Store observations of other agents' actions
        # For each observed action (donor, recipient), track whether they cooperated
        # We'll use a dict: (agent_id, 'donor'/'recipient') -> list of actions (True=cooperate, False=defect)
        self.observations = {}
        # Track how often we cooperated/defected in the past
        self.my_cooperations = 0
        self.my_defections = 0
        # Track memory of recent rounds for opponent-specific behavior
        self.recent_rounds = []  # list of (opponent_id, my_action, opp_action)
        # Keep a small history of cooperation rates for others
        self.coop_rates = {}  # agent_id -> rate (0-1)
        # Track whether we've seen this opponent before
        self.opponent_memory = {}  # opponent_id -> list of their actions

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            # Default to cooperate if no opponent info
            return True

        # If we've never seen this opponent, be cautiously cooperative
        if opponent not in self.opponent_memory or len(self.opponent_memory[opponent]) < 3:
            # In early encounters, cooperate to build trust, but defect occasionally
            # to avoid being exploited
            return random.random() < 0.7

        # Analyze opponent's behavior
        opp_actions = self.opponent_memory[opponent]
        coop_rate = sum(opp_actions) / len(opp_actions)

        # Check if opponent tends to defect after we cooperate (exploitative)
        # Look at sequences where we cooperated and see what they did next
        if len(self.recent_rounds) >= 2:
            # Get last interaction with this opponent
            last_interactions = [r for r in self.recent_rounds if r[0] == opponent]
            if last_interactions:
                last_opp_action = last_interactions[-1][2]
                if last_opp_action is not None and not last_opp_action:
                    # They defected last time we played them; be more cautious
                    if coop_rate < 0.4:
                        return False
                    return random.random() < 0.5

        # Basic strategy: cooperate if opponent cooperates often, defect if they defect often
        if coop_rate > 0.75:
            return True
        elif coop_rate < 0.3:
            return False
        else:
            # Mixed strategy: mostly cooperate but sometimes defect to avoid being taken advantage of
            return random.random() < (0.5 + 0.3 * (coop_rate - 0.5) * 2)

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update observations for each agent involved
        for agent_id, action_str in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                # Track our own actions
                if action_str == 'cooperate':
                    self.my_cooperations += 1
                else:
                    self.my_defections += 1
            else:
                # Track other agents' actions
                key = (agent_id, 'donor' if agent_id == donor_id else 'recipient')
                if key not in self.observations:
                    self.observations[key] = []
                self.observations[key].append(action_str == 'cooperate')

                # Update cooperation rate for this agent
                if agent_id not in self.coop_rates:
                    self.coop_rates[agent_id] = []
                self.coop_rates[agent_id].append(action_str == 'cooperate')

        # If we're involved in this interaction, update our memory of the opponent
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent
            opp_id = recipient_id if donor_id == self.agent_id else donor_id
            opp_action = recipient_action if donor_id == self.agent_id else donor_action
            my_action = donor_action if donor_id == self.agent_id else recipient_action

            # Store this interaction
            if opp_id not in self.opponent_memory:
                self.opponent_memory[opp_id] = []
            self.opponent_memory[opp_id].append(opp_action == 'cooperate')

            # Store in recent rounds (keep last 30)
            self.recent_rounds.append((opp_id, my_action == 'cooperate', opp_action == 'cooperate'))
            if len(self.recent_rounds) > 30:
                self.recent_rounds.pop(0)

        # Limit memory size to avoid unbounded growth
        if len(self.observations) > 1000:
            # Remove oldest entries
            keys = list(self.observations.keys())
            for k in keys[:len(keys)//2]:
                del self.observations[k]
        if len(self.coop_rates) > 1000:
            keys = list(self.coop_rates.keys())
            for k in keys[:len(keys)//2]:
                del self.coop_rates[k]

