class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round = 0
        self.gen = 0
        self.my_scores = {}
        self.reputation = {}
        self.generosity = 0.5
        self.trust = {}
        self.last_opponent = None
        self.last_action = None
        self.last_result = None
        self.observed = {}
        self.interactions = {}
        self.total_rounds = 30
        self.total_gens = 30
        self.memory = []
        self.coop_count = 0
        self.defect_count = 0
        self.opponent_history = {}
        self.self_history = []
        self.gen_start = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent
        if self.round < 2:
            # Start cooperative
            self.last_action = True
            return True

        # Estimate opponent cooperation probability
        opp_coop_prob = 0.5
        if opponent in self.opponent_history:
            hist = self.opponent_history[opponent]
            if len(hist) > 0:
                opp_coop_prob = sum(1 for a in hist if a) / len(hist)

        # My own reputation (how often I've cooperated)
        my_coop_rate = 0.5
        if len(self.self_history) > 0:
            my_coop_rate = sum(1 for a in self.self_history if a) / len(self.self_history)

        # Trust factor based on opponent's history
        trust_factor = 1.0
        if opponent in self.trust:
            trust_factor = self.trust[opponent]

        # Generosity parameter adjusts based on outcomes
        # If I've been exploited, become less generous
        if self.last_result == "exploited":
            self.generosity = max(0.1, self.generosity - 0.05)
        elif self.last_result == "cooperated":
            self.generosity = min(0.9, self.generosity + 0.02)

        # Adaptive strategy: cooperate with probability based on opponent and reputation
        coop_prob = 0.5 + 0.3 * (opp_coop_prob - 0.5) + 0.2 * (my_coop_rate - 0.5) + 0.1 * trust_factor
        coop_prob = max(0.1, min(0.9, coop_prob))

        # Use generosity to slightly favor cooperation
        coop_prob = coop_prob * (1 - self.generosity) + self.generosity * 0.5

        # Deterministic threshold based on round number and generation
        noise = 0.02 * math.sin(self.gen * 3.7 + self.round * 1.3 + self.agent_id)
        action = (coop_prob + noise) > 0.5

        self.last_action = action
        return action

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update round counters based on self observations
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # This is a self-judgment
            if donor_id == self.agent_id:
                self.last_result = "cooperated" if donor_action == "cooperate" else "defected"
            else:
                self.last_result = "cooperated" if recipient_action == "cooperate" else "defected"

            # Record my action
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            self.self_history.append(my_action == "cooperate")
            if my_action == "cooperate":
                self.coop_count += 1
            else:
                self.defect_count += 1

            # Update opponent history for my last opponent
            if self.last_opponent is not None:
                if self.last_opponent not in self.opponent_history:
                    self.opponent_history[self.last_opponent] = []
                # The opponent's action in this interaction
                if donor_id == self.agent_id:
                    opp_action = recipient_action
                else:
                    opp_action = donor_action
                self.opponent_history[self.last_opponent].append(opp_action == "cooperate")

                # Update trust based on outcome
                if self.last_result == "cooperated" and opp_action == "cooperate":
                    # Mutual cooperation increases trust
                    self.trust[self.last_opponent] = self.trust.get(self.last_opponent, 0) + 0.1
                elif self.last_result == "exploited":
                    self.trust[self.last_opponent] = self.trust.get(self.last_opponent, 0) - 0.15
                elif self.last_result == "defected":
                    self.trust[self.last_opponent] = self.trust.get(self.last_opponent, 0) - 0.05

        # Third-party observation: update reputation of both agents
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Track cooperation rate of each agent
            if donor_id not in self.reputation:
                self.reputation[donor_id] = [0, 0]  # [coop_count, total]
            if recipient_id not in self.reputation:
                self.reputation[recipient_id] = [0, 0]

            self.reputation[donor_id][1] += 1
            self.reputation[recipient_id][1] += 1
            if donor_action == "cooperate":
                self.reputation[donor_id][0] += 1
            if recipient_action == "cooperate":
                self.reputation[recipient_id][0] += 1

        # Track interactions for analysis
        key = (min(donor_id, recipient_id), max(donor_id, recipient_id))
        if key not in self.interactions:
            self.interactions[key] = []
        self.interactions[key].append((donor_action, recipient_action))

        # Increment round counter when a self observation occurs
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round += 1
            if self.round >= self.total_rounds:
                self.round = 0
                self.gen += 1
                # Reset trust slowly each generation
                for opp in self.trust:
                    self.trust[opp] *= 0.9
                # Reset per-generation history? Keep overall but decay
                if self.gen >= self.total_gens:
                    # End of simulation, no action needed
                    pass

