class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation scores for all agents (including self)
        # Initialize everyone to a neutral score of 0.0
        self.reputation = {}
        # Track cooperation counts (both given and received) per agent
        self.coop_given = {}
        self.coop_received = {}
        # Track total interactions observed per agent pair
        self.interactions = {}
        # Track each agent's tendency: last few actions for pattern detection
        self.action_history = {}  # agent_id -> list of ('cooperate'/'defect', as donor/recipient)
        # For personal strategy: track own history and outcomes
        self.own_actions = []  # list of (opponent_id, action, opponent_action)
        # For each opponent, track their cooperation rate in interactions with us
        self.opponent_coop_rate = {}  # opponent_id -> [coops, total]
        # For third-party observations, learn who cooperates generally
        self.general_coop_rate = {}  # agent_id -> [coops, total]
        # To detect if we are in a special situation (e.g., we've been exploited)
        self.exploited_count = 0
        self.cooperated_count = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # default cooperate if no opponent info

        # If we have no history with this opponent, start with cooperation
        # But check general reputation first
        if opponent not in self.opponent_coop_rate:
            # Use general reputation if available
            if opponent in self.general_coop_rate:
                coops, total = self.general_coop_rate[opponent]
                if total > 0:
                    coop_rate = coops / total
                    return coop_rate >= 0.5
            return True  # default cooperate

        # Personalized strategy based on opponent's cooperation rate with us
        coops, total = self.opponent_coop_rate[opponent]
        coop_rate = coops / total if total > 0 else 0.0

        # If opponent has cooperated at least 60% of the time, cooperate
        if coop_rate >= 0.6:
            return True
        # If opponent has defected more than 60% of the time, defect
        elif coop_rate <= 0.4:
            return False
        else:
            # Mixed history: use tit-for-tat with forgiveness
            # Check last interaction with this opponent
            if self.own_actions:
                for opp, action, opp_action in reversed(self.own_actions):
                    if opp == opponent:
                        # If last interaction we cooperated and they defected, defect now
                        if action and not opp_action:
                            return False
                        # If last interaction we defected and they cooperated, maybe forgive
                        if not action and opp_action:
                            # 20% chance to forgive and cooperate
                            return random.random() < 0.2
                        break
            # Otherwise cooperate
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update general cooperation rates for observed agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.general_coop_rate:
                self.general_coop_rate[agent_id] = [0, 0]
            self.general_coop_rate[agent_id][1] += 1
            if action == 'cooperate':
                self.general_coop_rate[agent_id][0] += 1
            # Track action history for pattern detection
            if agent_id not in self.action_history:
                self.action_history[agent_id] = []
            self.action_history[agent_id].append(action)
            # Keep history bounded (last 20 actions)
            if len(self.action_history[agent_id]) > 20:
                self.action_history[agent_id].pop(0)

        # Update reputation scores: cooperation increases rep, defection decreases
        # Simple additive model with bounds
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0.0
            if action == 'cooperate':
                self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + 0.1)
            else:
                self.reputation[agent_id] = max(-1.0, self.reputation[agent_id] - 0.2)

        # If we are involved in this interaction (as donor or recipient)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine who is the opponent
            opponent = recipient_id if donor_id == self.agent_id else donor_id
            # Determine our action and opponent's action
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
            else:
                my_action = recipient_action
                opp_action = donor_action

            # Update personal history
            self.own_actions.append((opponent, my_action == 'cooperate', opp_action == 'cooperate'))
            # Keep history bounded
            if len(self.own_actions) > 30:
                self.own_actions.pop(0)

            # Update opponent-specific cooperation rate
            if opponent not in self.opponent_coop_rate:
                self.opponent_coop_rate[opponent] = [0, 0]
            self.opponent_coop_rate[opponent][1] += 1
            if opp_action == 'cooperate':
                self.opponent_coop_rate[opponent][0] += 1

            # Track exploitation: we cooperated, they defected
            if my_action == 'cooperate' and opp_action == 'defect':
                self.exploited_count += 1
            if my_action == 'cooperate':
                self.cooperated_count += 1

        # Also track cooperation counts for each agent (given and received)
        for agent_id, action, is_donor in [(donor_id, donor_action, True), (recipient_id, recipient_action, False)]:
            if agent_id not in self.coop_given:
                self.coop_given[agent_id] = 0
                self.coop_received[agent_id] = 0
            if action == 'cooperate':
                if is_donor:
                    self.coop_given[agent_id] += 1
                else:
                    self.coop_received[agent_id] += 1

        # Track interactions between pairs for potential pattern detection
        pair = (min(donor_id, recipient_id), max(donor_id, recipient_id))
        if pair not in self.interactions:
            self.interactions[pair] = []
        self.interactions[pair].append((donor_action, recipient_action))
        # Keep bounded
        if len(self.interactions[pair]) > 20:
            self.interactions[pair].pop(0)

