class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round = 0
        self.total_rounds = 30
        self.generation = 0
        self.total_generations = 30
        self.reputation = {}
        self.own_history = {}
        self.others_coop_rate = 0.5
        self.others_total_obs = 0
        self.others_coop_obs = 0
        self.recent_actions = []
        self.recent_window = 10
        self.direct_opponent_recent = {}
        self.phase = 'early'
        self.base_coop_prob = 0.6
        self.forgiveness = 0.3
        self.retaliation = 0.7
        self.trust_threshold = 0.5
        self.own_coop_count = 0
        self.own_defect_count = 0

    def decide(self) -> bool:
        if self.generation == self.total_generations - 1 and self.round == self.total_rounds - 1:
            return False

        if self.generation < self.total_generations * 0.3:
            self.phase = 'early'
        elif self.generation < self.total_generations * 0.7:
            self.phase = 'mid'
        else:
            self.phase = 'late'

        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return True

        if opponent_id in self.reputation:
            coop, defect = self.reputation[opponent_id]
            total_obs = coop + defect
            if total_obs > 0:
                opp_coop_rate = coop / total_obs
            else:
                opp_coop_rate = 0.5
        else:
            opp_coop_rate = self.others_coop_rate if self.others_total_obs > 0 else 0.5

        if opponent_id in self.direct_opponent_recent:
            direct_actions = self.direct_opponent_recent[opponent_id]
            if direct_actions:
                direct_coop = sum(direct_actions) / len(direct_actions)
                weight_direct = min(0.7, len(direct_actions) / 10)
                opp_coop_rate = (1 - weight_direct) * opp_coop_rate + weight_direct * direct_coop

        if self.phase == 'early':
            base = 0.7
        elif self.phase == 'mid':
            base = 0.5
        else:
            base = 0.3

        if opp_coop_rate > self.trust_threshold:
            prob = base + 0.2 * (opp_coop_rate - self.trust_threshold) / (1 - self.trust_threshold)
        else:
            prob = base - 0.3 * (self.trust_threshold - opp_coop_rate) / self.trust_threshold

        prob = max(0.0, min(1.0, prob))

        return random.random() < prob

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        is_self = (donor_id == self.agent_id) or (recipient_id == self.agent_id)

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                if agent_id not in self.reputation:
                    self.reputation[agent_id] = [0, 0]
                if action == 'cooperate':
                    self.reputation[agent_id][0] += 1
                else:
                    self.reputation[agent_id][1] += 1
                if not is_self:
                    self.others_total_obs += 1
                    if action == 'cooperate':
                        self.others_coop_obs += 1

        if donor_id == self.agent_id:
            self.own_coop_count += 1 if donor_action == 'cooperate' else 0
            self.own_defect_count += 1 if donor_action == 'defect' else 0
            my_action = (donor_action == 'cooperate')
            self.recent_actions.append(my_action)
            if len(self.recent_actions) > self.recent_window:
                self.recent_actions.pop(0)
            opp_id = recipient_id
            opp_action = (recipient_action == 'cooperate')
            if opp_id not in self.direct_opponent_recent:
                self.direct_opponent_recent[opp_id] = []
            self.direct_opponent_recent[opp_id].append(opp_action)
            if len(self.direct_opponent_recent[opp_id]) > 10:
                self.direct_opponent_recent[opp_id].pop(0)
        elif recipient_id == self.agent_id:
            self.own_coop_count += 1 if recipient_action == 'cooperate' else 0
            self.own_defect_count += 1 if recipient_action == 'defect' else 0
            my_action = (recipient_action == 'cooperate')
            self.recent_actions.append(my_action)
            if len(self.recent_actions) > self.recent_window:
                self.recent_actions.pop(0)
