            self.general_coop_rate[agent_id][1] += 1
            if action == 'cooperate':
                self.general_coop_rate[agent_id][0] += 1
            # Track action history for pattern detection
            if agent_id not in self.action_history:
                self.action_history[agent_id] = []
            self.action_history[agent_id].append(action)
            # Keep history bounded (last 20 actions)
            if len(self.action_history[agent_id]) > 20:
                self.action_history[agent_id].pop(0)

        # Update reputation scores: cooperation increases rep, defection decreases
        # Simple additive model with bounds
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0.0
            if action == 'cooperate':
                self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + 0.1)
            else:
                self.reputation[agent_id] = max(-1.0, self.reputation[agent_id] - 0.2)

        # If we are involved in this interaction (as donor or recipient)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine who is the opponent
            opponent = recipient_id if donor_id == self.agent_id else donor_id
            # Determine our action and opponent's action
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
            else:
                my_action = recipient_action
                opp_action = donor_action

            # Update personal history
            self.own_actions.append((opponent, my_action == 'cooperate', opp_action == 'cooperate'))
            # Keep history bounded
            if len(self.own_actions) > 30:
                self.own_actions.pop(0)

            # Update opponent-specific cooperation rate
            if opponent not in self.opponent_coop_rate:
                self.opponent_coop_rate[opponent] = [0, 0]
            self.opponent_coop_rate[opponent][1] += 1
            if opp_action == 'cooperate':
                self.opponent_coop_rate[opponent][0] += 1

            # Track exploitation: we cooperated, they defected
            if my_action == 'cooperate' and opp_action == 'defect':
                self.exploited_count += 1
            if my_action == 'cooperate':
                self.cooperated_count += 1

        # Also track cooperation counts for each agent (given and received)
        for agent_id, action, is_donor in [(donor_id, donor_action, True), (recipient_id, recipient_action, False)]:
            if agent_id not in self.coop_given:
                self.coop_given[agent_id] = 0
                self.coop_received[agent_id] = 0
            if action == 'cooperate':
                if is_donor:
                    self.coop_given[agent_id] += 1
                else:
                    self.coop_received[agent_id] += 1

        # Track interactions between pairs for potential pattern detection
        pair = (min(donor_id, recipient_id), max(donor_id, recipient_id))
        if pair not in self.interactions:
            self.interactions[pair] = []
        self.interactions[pair].append((donor_action, recipient_action))
        # Keep bounded
        if len(self.interactions[pair]) > 20:
            self.interactions[pair].pop(0)

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round = 0
        self.total_rounds = 30
        self.generation = 0
        self.total_generations = 30
        self.reputation = {}
        self.own_history = {}
        self.others_coop_rate = 0.5
        self.others_total_obs = 0
        self.others_coop_obs = 0
        self.recent_actions = []
        self.recent_window = 10
        self.direct_opponent_recent = {}
        self.phase = 'early'
        self.base_coop_prob = 0.6
        self.forgiveness = 0.3
        self.retaliation = 0.7
        self.trust_threshold = 0.5
        self.own_coop_count = 0
        self.own_defect_count = 0

    def decide(self) -> bool:
        if self.generation == self.total_generations - 1 and self.round == self.total_rounds - 1:
            return False

        if self.generation < self.total_generations * 0.3:
            self.phase = 'early'
        elif self.generation < self.total_generations * 0.7:
            self.phase = 'mid'
        else:
            self.phase = 'late'

        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return True

        if opponent_id in self.reputation:
            coop, defect = self.reputation[opponent_id]
            total_obs = coop + defect
            if total_obs > 0:
                opp_coop_rate = coop / total_obs
            else:
                opp_coop_rate = 0.5
        else:
            opp_coop_rate = self.others_coop_rate if self.others_total_obs > 0 else 0.5

        if opponent_id in self.direct_opponent_recent:
            direct_actions = self.direct_opponent_recent[opponent_id]
            if direct_actions:
                direct_coop = sum(direct_actions) / len(direct_actions)
                weight_direct = min(0.7, len(direct_actions) / 10)
                opp_coop_rate = (1 - weight_direct) * opp_coop_rate + weight_direct * direct_coop

        if self.phase == 'early':
            base = 0.7
        elif self.phase == 'mid':
            base = 0.5
        else:
            base = 0.3

        if opp_coop_rate > self.trust_threshold:
            prob = base + 0.2 * (opp_coop_rate - self.trust_threshold) / (1 - self.trust_threshold)
        else:
            prob = base - 0.3 * (self.trust_threshold - opp_coop_rate) / self.trust_threshold

        prob = max(0.0, min(1.0, prob))

        return random.random() < prob

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        is_self = (donor_id == self.agent_id) or (recipient_id == self.agent_id)

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                if agent_id not in self.reputation:
                    self.reputation[agent_id] = [0, 0]
                if action == 'cooperate':
                    self.reputation[agent_id][0] += 1
                else:
                    self.reputation[agent_id][1] += 1
                if not is_self:
                    self.others_total_obs += 1
                    if action == 'cooperate':
                        self.others_coop_obs += 1

        if donor_id == self.agent_id:
            self.own_coop_count += 1 if donor_action == 'cooperate' else 0
            self.own_defect_count += 1 if donor_action == 'defect' else 0
            my_action = (donor_action == 'cooperate')
            self.recent_actions.append(my_action)
            if len(self.recent_actions) > self.recent_window:
                self.recent_actions.pop(0)
            opp_id = recipient_id
            opp_action = (recipient_action == 'cooperate')
            if opp_id not in self.direct_opponent_recent:
                self.direct_opponent_recent[opp_id] = []
            self.direct_opponent_recent[opp_id].append(opp_action)
            if len(self.direct_opponent_recent[opp_id]) > 10:
                self.direct_opponent_recent[opp_id].pop(0)
        elif recipient_id == self.agent_id:
            self.own_coop_count += 1 if recipient_action == 'cooperate' else 0
            self.own_defect_count += 1 if recipient_action == 'defect' else 0
            my_action = (recipient_action == 'cooperate')
            self.recent_actions.append(my_action)
            if len(self.recent_actions) > self.recent_window:
                self.recent_actions.pop(0)
            opp_id = donor_id
            opp_action = (donor_action == 'cooperate')
            if opp_id not in self.direct_opponent_recent:
                self.direct_opponent_recent[opp_id] = []
            self.direct_opponent_recent[opp_id].append(opp_action)
            if len(self.direct_opponent_recent[opp_id]) > 10:
                self.direct_opponent_recent[opp_id].pop(0)

        if self.others_total_obs > 0:
            self.others_coop_rate = self.others_coop_obs / self.others_total_obs

