import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores: agent_id -> score (higher means more cooperative)
        self.reputation = {}
        # Interaction counts with each agent: agent_id -> (coop, defect, total)
        self.interactions = {}
        # Memory of recent outcomes with each agent (last 10 interactions)
        self.recent = {}
        # Current opponent for this round
        self._ctx_opponent_id = None
        # Global cooperation rate estimate
        self.global_coop_rate = 0.5
        # Track self behavior and partner behavior history
        self.my_history = []
        self.partner_history = []
        # Generosity factor - decreases over time if exploited
        self.generosity = 1.0
        # Counter for rounds played
        self.round_count = 0

    def _update_reputation(self, donor_id, action):
        if action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + 0.1
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - 0.15
        # Clamp reputation to [0, 1]
        self.reputation[donor_id] = max(0.0, min(1.0, self.reputation[donor_id]))

    def _update_interaction(self, partner_id, my_action, partner_action):
        if partner_id not in self.interactions:
            self.interactions[partner_id] = [0, 0, 0]  # [coop, defect, total]
        stats = self.interactions[partner_id]
        if my_action == 'cooperate':
            stats[0] += 1
        else:
            stats[1] += 1
        stats[2] += 1
        # Update recent memory (keep last 10)
        if partner_id not in self.recent:
            self.recent[partner_id] = []
        self.recent[partner_id].append((my_action, partner_action))
        if len(self.recent[partner_id]) > 10:
            self.recent[partner_id].pop(0)

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both actors
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # If we are involved, update interaction stats
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            partner_id = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            partner_action = recipient_action if donor_id == self.agent_id else donor_action
            self._update_interaction(partner_id, my_action, partner_action)
            self.round_count += 1
            # Track own and partner actions for adaptive strategy
            self.my_history.append(my_action)
            self.partner_history.append(partner_action)
            # Update generosity based on own experience
            if partner_action == 'defect' and my_action == 'cooperate':
                self.generosity *= 0.95  # reduce generosity when exploited
            elif partner_action == 'cooperate' and my_action == 'cooperate':
                self.generosity = min(1.0, self.generosity * 1.01)  # slight increase

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True  # fallback
        opponent = self._ctx_opponent_id
        opp_rep = self.reputation.get(opponent, 0.5)

        # If we have interaction history with this opponent
        if opponent in self.interactions:
            stats = self.interactions[opponent]
            total = stats[2]
            if total > 0:
                my_coop_rate = stats[0] / total
                # If opponent has mostly defected against us, retaliate
                if opp_rep < 0.35:
                    return False
                # If we have cooperated a lot and opponent still defects, defect
                if my_coop_rate > 0.7 and opp_rep < 0.5:
                    return False
                # Forgiving tit-for-tat: cooperate if opponent's recent actions are mostly cooperative
                if opponent in self.recent and len(self.recent[opponent]) > 0:
                    recent_partner_actions = [a for (_, a) in self.recent[opponent]]
                    coop_count = recent_partner_actions.count('cooperate')
                    if coop_count / len(recent_partner_actions) >= 0.5:
                        return True
                    else:
                        # If opponent has been defective recently, maybe defect with some probability
                        # but keep some chance to cooperate to avoid endless defection
                        if len(recent_partner_actions) >= 3 and coop_count == 0:
                            return False
                        # Otherwise, use a mixed strategy
                        defect_prob = 0.3 + (1 - self.generosity) * 0.4
                        return random.random() > defect_prob
                else:
                    # No recent memory yet, use reputation
                    return random.random() < (0.5 + opp_rep * 0.3)
            else:
                # No interactions yet, use reputation
                return random.random() < (0.5 + opp_rep * 0.3)
        else:
            # Unknown opponent, base on reputation and global rate
            # Be initially cooperative but not too foolish
            if opp_rep > 0.6:
                return True
            elif opp_rep < 0.3:
                return False
            else:
                # Use stochastic based on global cooperation rate
                return random.random() < (self.global_coop_rate * 0.8 + 0.1)

