import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.total_actions = {}
        self.coop_with = {}
        self.interactions_count = {}
        self.recent_outcomes = []
        self.generation = 0
        self.round = 0
        self.opponent_id = None
        self.my_coop_rate = 1.0
        self.my_total_actions = 0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        self.opponent_id = opp
        prob_coop = 0.7

        opp_rep = self.reputation.get(opp, 0.0)
        rep_factor = max(0.0, min(1.0, (opp_rep + 5) / 10.0))
        prob_coop = prob_coop * (0.5 + 0.5 * rep_factor)

        coop_with_opp = self.coop_with.get(opp, 0)
        inter_count = self.interactions_count.get(opp, 0)
        if inter_count > 0:
            direct_rep = coop_with_opp / inter_count
            prob_coop = 0.5 * prob_coop + 0.5 * direct_rep

        recent_opp_outcomes = [o for o in self.recent_outcomes if o[0] == opp]
        if len(recent_opp_outcomes) >= 3:
            opp_defections = sum(1 for o in recent_opp_outcomes[-3:] if not o[2])
            if opp_defections >= 2:
                prob_coop *= 0.3

        if self.my_total_actions > 5:
            if self.my_coop_rate > 0.6 and self._global_defection_rate() > 0.5:
                prob_coop *= 0.8

        rng = random.Random(self.agent_id * 1000 + self.generation * 10 + self.round)
        return rng.random() < prob_coop

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + 1
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) - 1.5
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + 1
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) - 1.5

        self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.total_actions[donor_id] = self.total_actions.get(donor_id, 0) + 1
        self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.total_actions[recipient_id] = self.total_actions.get(recipient_id, 0) + 1

        if donor_id == self.agent_id:
            opp = recipient_id
            self.coop_with[opp] = self.coop_with.get(opp, 0) + (1 if donor_action == 'cooperate' else 0)
            self.interactions_count[opp] = self.interactions_count.get(opp, 0) + 1
            self.recent_outcomes.append((opp, donor_action == 'cooperate', recipient_action == 'cooperate'))
            self.my_total_actions += 1
            if donor_action == 'cooperate':
                self.my_coop_rate = (self.my_coop_rate * (self.my_total_actions - 1) + 1) / self.my_total_actions
            else:
                self.my_coop_rate = (self.my_coop_rate * (self.my_total_actions - 1)) / self.my_total_actions
        elif recipient_id == self.agent_id:
            opp = donor_id
            self.coop_with[opp] = self.coop_with.get(opp, 0) + (1 if recipient_action == 'cooperate' else 0)
            self.interactions_count[opp] = self.interactions_count.get(opp, 0) + 1
            self.recent_outcomes.append((opp, recipient_action == 'cooperate', donor_action == 'cooperate'))
            self.my_total_actions += 1
            if recipient_action == 'cooperate':
                self.my_coop_rate = (self.my_coop_rate * (self.my_total_actions - 1) + 1) / self.my_total_actions
            else:
                self.my_coop_rate = (self.my_coop_rate * (self.my_total_actions - 1)) / self.my_total_actions

        if len(self.recent_outcomes) > 100:
            self.recent_outcomes = self.recent_outcomes[-100:]

    def _global_defection_rate(self):
        if not self.reputation:
            return 0.5
        avg_rep = sum(self.reputation.values()) / len(self.reputation)
        return max(0.0, min(1.0, 0.5 - avg_rep / 10))

