import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation: key is agent ID, value is a list of observed actions (True=cooperate, False=defect)
        self.reputation = {}
        # Track count of cooperative vs defection actions by each agent
        self.coop_count = {}
        self.defect_count = {}
        # Track own interactions: key is opponent ID, value is list of (my_action, their_action)
        self.interactions = {}
        # Track partner-specific trust scores (0-1)
        self.trust = {}
        # Track recent outcomes for sliding window (last 10 interactions with any partner)
        self.recent_outcomes = []
        # Generosity parameter: tendency to cooperate with unknown agents
        self.generosity = 0.7
        # Threshold for cooperation based on reputation
        self.reputation_threshold = 0.6
        # Learning rate for updating trust
        self.alpha = 0.2
        # For random exploration occasionally
        self.exploration_rate = 0.05
        # Track generation number if needed (not directly given, but can infer from rounds)
        self.total_rounds = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # First interaction with this opponent? Use general reputation
        if opponent not in self.interactions or len(self.interactions[opponent]) == 0:
            # Get reputation if available
            rep = self.reputation.get(opponent, 0.5)
            # Cooperate if reputation above threshold, with some generosity
            if rep >= self.reputation_threshold:
                return True
            else:
                # If reputation is low, defect, but sometimes explore
                if random.random() < self.exploration_rate:
                    return True
                return False
        else:
            # Have history with this opponent, use trust score
            trust = self.trust.get(opponent, 0.5)
            # If trust high, cooperate
            if trust >= 0.6:
                return True
            # If trust low, defect but sometimes explore
            elif trust <= 0.4:
                if random.random() < self.exploration_rate:
                    return True
                return False
            else:
                # Moderate trust, base on recent outcomes
                recent = self.recent_outcomes[-10:]
                if recent:
                    coop_rate = sum(1 for (my, their) in recent if their)
                    if coop_rate / len(recent) > 0.5:
                        return True
                    else:
                        return False
                else:
                    return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both donor and recipient
        for (agent_id, action) in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            is_coop = (action == 'cooperate')
            # Update coop/defect counts
            if is_coop:
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            else:
                self.defect_count[agent_id] = self.defect_count.get(agent_id, 0) + 1
            # Compute reputation as fraction of cooperative actions
            total = self.coop_count.get(agent_id, 0) + self.defect_count.get(agent_id, 0)
            if total > 0:
                self.reputation[agent_id] = self.coop_count.get(agent_id, 0) / total
            else:
                self.reputation[agent_id] = 0.5

