class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        # Reputation tracking: map opponent_id -> (cooperations, defections) observed
        self.reputation = {}
        # Track own interactions: opponent_id -> list of (my_action, their_action)
        self.interactions = {}
        # Track who we've cooperated with and their reciprocation
        self.cooperation_history = {}
        # Track how often we've defected and the outcome
        self.defection_history = {}
        # Track overall trust level per opponent based on their actions
        self.trust = {}
        # Track generations if needed
        self.generation = 0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        # If we have no info, start with cautious cooperation
        if opp not in self.trust:
            return True
        # Trust threshold: cooperate if trust >= 0.5
        trust_val = self.trust[opp]
        return trust_val >= 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both agents involved
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                # Self-observation: update our own stats
                if agent_id not in self.reputation:
                    self.reputation[agent_id] = [0, 0]
                if action == 'cooperate':
                    self.reputation[agent_id][0] += 1
                else:
                    self.reputation[agent_id][1] += 1
                # Update own interaction history if we were involved
                if donor_id == self.agent_id:
                    other = recipient_id
                    other_action = recipient_action
                else:
                    other = donor_id
                    other_action = donor_action
                if other not in self.interactions:
                    self.interactions[other] = []
                self.interactions[other].append((action, other_action))
                # Update trust based on our interaction: if we cooperated and they cooperated -> good
                # If we defected and they defected -> neutral? For simplicity, update trust
                if action == 'cooperate':
                    if other_action == 'cooperate':
                        self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1 * 1.0
                    else:
                        self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1 * 0.0
                else:
                    # Defection: if they also defected, maybe they are retaliatory, but not cooperative
                    # Keep trust lower
                    self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1 * 0.2
            else:
                # Third-party observation: update reputation
                if agent_id not in self.reputation:
                    self.reputation[agent_id] = [0, 0]
                if action == 'cooperate':
                    self.reputation[agent_id][0] += 1
                else:
                    self.reputation[agent_id][1] += 1
                # Update trust based on their observed actions
                # If they cooperate often, increase trust; if defect, decrease
                coop_count = self.reputation[agent_id][0]
                def_count = self.reputation[agent_id][1]
                total = coop_count + def_count
                if total > 0:
                    coop_ratio = coop_count / total
                    # Update trust with a moving average, but also consider recentness
                    # Simple: trust = coop_ratio weighted with previous trust
                    self.trust[agent_id] = 0.8 * self.trust.get(agent_id, 0.5) + 0.2 * coop_ratio
                # Also track cooperation history for potential reciprocation
                if donor_id == recipient_id:
                    # Not possible, but just in case
                    pass
                # If we observed a player defecting against someone who cooperated, lower trust more
                if donor_action == 'defect' and recipient_action == 'cooperate':
                    self.trust[donor_id] = self.trust.get(donor_id, 0.5) * 0.9 + 0.1 * 0.0
                if recipient_action == 'defect' and donor_action == 'cooperate':
                    self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) * 0.9 + 0.1 * 0.0
        # Also update own interaction history for self-judgment
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Already handled above, but ensure we record
            pass

