        opp = self._ctx_opponent_id
        if opp is None:
            return True
        # If we have no info, start with cautious cooperation
        if opp not in self.trust:
            return True
        # Trust threshold: cooperate if trust >= 0.5
        trust_val = self.trust[opp]
        return trust_val >= 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both agents involved
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                # Self-observation: update our own stats
                if agent_id not in self.reputation:
                    self.reputation[agent_id] = [0, 0]
                if action == 'cooperate':
                    self.reputation[agent_id][0] += 1
                else:
                    self.reputation[agent_id][1] += 1
                # Update own interaction history if we were involved
                if donor_id == self.agent_id:
                    other = recipient_id
                    other_action = recipient_action
                else:
                    other = donor_id
                    other_action = donor_action
                if other not in self.interactions:
                    self.interactions[other] = []
                self.interactions[other].append((action, other_action))
                # Update trust based on our interaction: if we cooperated and they cooperated -> good
                # If we defected and they defected -> neutral? For simplicity, update trust
                if action == 'cooperate':
                    if other_action == 'cooperate':
                        self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1 * 1.0
                    else:
                        self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1 * 0.0
                else:
                    # Defection: if they also defected, maybe they are retaliatory, but not cooperative
                    # Keep trust lower
                    self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1 * 0.2
            else:
                # Third-party observation: update reputation
                if agent_id not in self.reputation:
