        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)
        if donor_id == self.agent_id:
            self.personal_history.setdefault(recipient_id, []).append(recipient_action)
            self.my_last_action = donor_action
            self.my_last_opponent = recipient_id
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.my_last_outcome = 1.0
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.my_last_outcome = -1.0
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.my_last_outcome = 1.0
            else:
                self.my_last_outcome = -0.5
        elif recipient_id == self.agent_id:
            self.personal_history.setdefault(donor_id, []).append(donor_action)
            self.my_last_action = recipient_action
            self.my_last_opponent = donor_id
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.my_last_outcome = 1.0
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.my_last_outcome = -0.5
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.my_last_outcome = 1.0
            else:
                self.my_last_outcome = -1.0

    def _update_reputation(self, agent_id: int, action: str) -> None:
        self.total_observed[agent_id] = self.total_observed.get(agent_id, 0) + 1
        if action == 'cooperate':
            self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
        total = self.total_observed[agent_id]
        coop = self.coop_count.get(agent_id, 0)
        rate = coop / total
        prev = self.reputation.get(agent_id, self.default_reputation)
        self.reputation[agent_id] = self.alpha * rate + (1 - self.alpha) * prev

