class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation scores: maps agent_id -> reputation (0.0 to 1.0)
        self.reputation = {}
        # Track cooperation counts per agent
        self.coop_counts = {}
        self.total_obs = {}
        # Track recent interactions for each opponent
        self.history = {}  # opponent_id -> list of (my_action, their_action)
        # Parameters for reputation update
        self.alpha = 0.1  # learning rate for reputation updates
        self.beta = 0.05  # decay factor for older observations
        # Personal tolerance for defection
        self.forgiveness = 0.7
        # Track own performance
        self.my_coop_count = 0
        self.my_total_interactions = 0
        # Track defection ratio of opponents
        self.defect_ratio = {}
        self._ctx_opponent_id = None

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True  # default cooperate if no opponent info

        # Get reputation of opponent (default 0.5 if unknown)
        rep = self.reputation.get(opp, 0.5)

        # Get history with this opponent
        hist = self.history.get(opp, [])
        if len(hist) >= 3:
            # Look at recent patterns: if opponent defected twice in a row recently, be cautious
            recent_actions = [a for _, a in hist[-3:]]
            if recent_actions.count('defect') >= 2:
                return random.random() > 0.2  # 80% chance to defect if they've defected recently twice

        # Base decision on reputation
        if rep > 0.6:
            # Trustworthy opponent: cooperate with high probability
            return random.random() < 0.95
        elif rep > 0.4:
            # Neutral: cooperate with moderate probability
            return random.random() < 0.6
        else:
            # Low reputation: defect mostly
            return random.random() < 0.2

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            # Update own interaction history if we are involved
            if donor_id == self.agent_id or recipient_id == self.agent_id:
                if donor_id == self.agent_id:
                    my_action = donor_action
                    their_action = recipient_action
                    opp = recipient_id
                else:
                    my_action = recipient_action
                    their_action = donor_action
                    opp = donor_id

                # Update own stats
                self.my_total_interactions += 1
                if my_action == 'cooperate':
                    self.my_coop_count += 1

                # Record history
                if opp not in self.history:
                    self.history[opp] = []
