                if their_action == 'defect':
                    self.defect_ratio[opp]['defects'] += 1

            # Update reputation for both donor and recipient based on their actions
            # For donor: cooperating increases reputation, defecting decreases
            if donor_id != self.agent_id:
                self._update_reputation(donor_id, donor_action == 'cooperate')
            # For recipient: their action also matters but less so
            if recipient_id != self.agent_id:
                self._update_reputation(recipient_id, recipient_action == 'cooperate', weight=0.5)

