    def _update_reputation(self, agent_id: int, cooperated: bool, weight: float = 1.0):
        """Update reputation score for an agent based on observed action."""
        # Get current reputation, default 0.5
        current = self.reputation.get(agent_id, 0.5)
        # Update: if cooperated, increase; if defected, decrease
        # Use a bounded update to keep within [0,1]
        if cooperated:
            new_rep = current + self.alpha * weight * (1 - current)
        else:
            new_rep = current - self.alpha * weight * current
        # Clamp to [0,1]
        self.reputation[agent_id] = max(0.0, min(1.0, new_rep))

        # Track observation counts for decay
        if agent_id not in self.total_obs:
            self.total_obs[agent_id] = 0
        self.total_obs[agent_id] += 1
        # Apply decay to older reputation values occasionally
        if self.total_obs[agent_id] % 10 == 0:
