class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> reputation score (0..1)
        self.cooperation_history = {}  # agent_id -> list of actions observed from this agent
        self.my_history = []  # my past actions
        self.opponent_history = {}  # opponent_id -> list of actions against me
        self.rounds_played = 0
        self.total_coop = 0
        self.total_defect = 0
        self.alpha = 0.1  # learning rate for reputation updates
        self.decay = 0.99

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # If we have no info, be cooperative initially
        if opponent not in self.reputation:
            return True

        rep = self.reputation.get(opponent, 0.5)
        # If opponent has good reputation, cooperate; otherwise defect
        # Add slight randomness to avoid being completely predictable
        if rep > 0.6:
            return True
        elif rep < 0.4:
            return False
        else:
            # Mixed strategy based on history of our interactions
            if opponent in self.opponent_history:
                their_actions = self.opponent_history[opponent]
                if their_actions:
                    coop_rate = sum(1 for a in their_actions if a == 'cooperate') / len(their_actions)
                    if coop_rate > 0.5:
                        return True
                    else:
                        return False
            return random.random() > 0.3  # default slightly cooperative

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update own history if involved
        if donor_id == self.agent_id:
            self.my_history.append(donor_action)
            self.total_coop += 1 if donor_action == 'cooperate' else 0
            self.total_defect += 1 if donor_action == 'defect' else 0
        if recipient_id == self.agent_id:
            # record what opponent did to us
            opp = donor_id
            if opp not in self.opponent_history:
                self.opponent_history[opp] = []
            self.opponent_history[opp].append(donor_action)

        # Update reputation of both agents based on their actions
        # Reputation update: cooperate adds, defect subtracts
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # Decay old reputations slightly
        for agent in list(self.reputation.keys()):
            self.reputation[agent] *= self.decay

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        # Update reputation: cooperate increases, defect decreases
        if action == 'cooperate':
            self.reputation[agent_id] += self.alpha * (1 - self.reputation[agent_id])
        else:
            self.reputation[agent_id] -= self.alpha * self.reputation[agent_id]
        # Keep in bounds
        self.reputation[agent_id] = max(0.0, min(1.0, self.reputation[agent_id]))

