        opp_reputation = self._reputation.get(opp, 0.5)
        if opp_reputation < 0.3:
            return False
        elif opp_reputation > 0.7:
            return True
        else:
            threshold = 0.5 + (opp_reputation - 0.5) * 0.4
            return random.random() < threshold

