        self._defect_counts[donor_id] = self._defect_counts.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)
        self._coop_counts[recipient_id] = self._coop_counts.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
