import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.my_actions = []
        self.their_actions = {}
        self.coop_count = 0
        self.defect_count = 0
        self.partner_history = {}
        self.round_num = 0
        self.generation_num = 0
        self.total_rounds = 0
        self.was_self_judged = False

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Get opponent's recent behavior
        opp_recent = self.their_actions.get(opponent, [])
        if len(opp_recent) >= 3:
            recent_coop = sum(1 for a in opp_recent[-3:] if a)
            if recent_coop >= 2:
                # Cooperate with cooperative opponents
                return True
            elif recent_coop <= 1:
                # Defect against mostly defecting opponents
                return False
        # If no history, check reputation
        rep = self.reputation.get(opponent, 0.5)
        if rep > 0.65:
            return True
        elif rep < 0.4:
            return False
        # Default: cooperate with some randomness based on own cooperation rate
        if self.coop_count + self.defect_count > 0:
            my_coop_rate = self.coop_count / (self.coop_count + self.defect_count)
            if my_coop_rate > 0.7:
                return True
            else:
                return random.random() < 0.4
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for donor and recipient
        donor_coop = donor_action == 'cooperate'
        recipient_coop = recipient_action == 'cooperate'

        # Update donor reputation: cooperating is good, defecting is bad
        if donor_id != self.agent_id:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5)
            if donor_coop:
                self.reputation[donor_id] += 0.1
            else:
                self.reputation[donor_id] -= 0.15
            self.reputation[donor_id] = max(0.0, min(1.0, self.reputation[donor_id]))

        # Update recipient reputation: receiving cooperation is neutral, but defecting is bad
        if recipient_id != self.agent_id:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5)
            if recipient_coop:
                self.reputation[recipient_id] += 0.05
            else:
                self.reputation[recipient_id] -= 0.2
            self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation[recipient_id]))

        # Track own actions and partner behavior when involved
        if donor_id == self.agent_id:
            self.my_actions.append(donor_coop)
            if donor_coop:
                self.coop_count += 1
            else:
                self.defect_count += 1
            # Track partner's action in this interaction
            partner_id = recipient_id
            self.their_actions.setdefault(partner_id, []).append(recipient_coop)
            # Keep only last 10 actions per partner
            if len(self.their_actions[partner_id]) > 10:
                self.their_actions[partner_id] = self.their_actions[partner_id][-10:]
        elif recipient_id == self.agent_id:
            self.my_actions.append(recipient_coop)
            if recipient_coop:
                self.coop_count += 1
            else:
                self.defect_count += 1
            # Track partner's action
            partner_id = donor_id
            self.their_actions.setdefault(partner_id, []).append(donor_coop)
            if len(self.their_actions[partner_id]) > 10:
                self.their_actions[partner_id] = self.their_actions[partner_id][-10:]

        # Increment round tracking if self-observed (each round has exactly one self observation)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.total_rounds += 1
            if self.total_rounds % 30 == 0:
                self.generation_num += 1

