import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores for all agents (including self). Start neutral.
        self.reputation = {}
        # Track cooperation counts for each agent to adjust expectations
        self.coop_counts = {}
        self.total_observations = {}
        # Memory of recent interactions: for each opponent, store last actions
        self.interaction_history = {}
        # Generosity/forgiveness parameter
        self.forgiveness = 0.1
        # Base trust threshold
        self.trust_threshold = 0.5

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # default cooperate if no opponent info
        # Get reputation of opponent (if unknown, assume neutral 0.5)
        opp_rep = self.reputation.get(opponent, 0.5)
        # Get history with this opponent
        history = self.interaction_history.get(opponent, [])
        # If we have interacted recently, apply reciprocity
        if history:
            # Last action of opponent (if any)
            last_opp_action = history[-1][1] if history else None
            # If opponent defected last time, be more likely to defect
            if last_opp_action == 'defect':
                # Defect with high probability unless reputation is very high
                if opp_rep > 0.8:
                    return random.random() < 0.7  # still mostly cooperate
                else:
                    return random.random() < 0.2  # mostly defect
            else:
                # If opponent cooperated last time, cooperate unless reputation low
                if opp_rep < 0.3:
                    return random.random() < 0.3
                else:
                    return random.random() < 0.9
        else:
            # No history: base decision on reputation
            return random.random() < opp_rep

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        # Update reputation for both donor and recipient
        # Simple reputation: increase for cooperate, decrease for defect
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0.5
                self.coop_counts[agent_id] = 0
                self.total_observations[agent_id] = 0
            self.total_observations[agent_id] += 1
            if action == 'cooperate':
                self.coop_counts[agent_id] += 1
                # Update reputation: move towards higher value
                self.reputation[agent_id] += 0.05
            else:
                # Decrease reputation
                self.reputation[agent_id] -= 0.05
            # Keep reputation in [0,1]
            self.reputation[agent_id] = max(0.0, min(1.0, self.reputation[agent_id]))

        # Track interaction history if we are one of the participants
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent
            if donor_id == self.agent_id:
                opponent = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opponent = donor_id
                my_action = recipient_action
                opp_action = donor_action
            if opponent not in self.interaction_history:
                self.interaction_history[opponent] = []
            self.interaction_history[opponent].append((my_action, opp_action))
            # Keep history limited to last 10 interactions
            if len(self.interaction_history[opponent]) > 10:
                self.interaction_history[opponent] = self.interaction_history[opponent][-10:]

        # Adjust reputation more strongly if we are the victim of defection
        if (donor_id == self.agent_id and recipient_action == 'defect') or \
           (recipient_id == self.agent_id and donor_action == 'defect'):
            # Someone defected against us: lower their reputation more
            if donor_id == self.agent_id:
                offender = recipient_id
            else:
                offender = donor_id
            if offender not in self.reputation:
                self.reputation[offender] = 0.5
            self.reputation[offender] -= 0.1
            self.reputation[offender] = max(0.0, min(1.0, self.reputation[offender]))

