import math

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.own_action_history = []
        self.observed_actions = {}
        self.cooperation_count = 0
        self.defection_count = 0
        self.round_num = 0
        self.opponent_history = {}
        self.trust_threshold = 0.5
        self.base_cooperation_probability = 0.7
        self.reciprocity_factor = 0.8
        self.reputation_weight = 0.3
        self.personal_experience_weight = 0.5
        self.observation_weight = 0.2
        self.reputation_decay = 0.95
        self.min_trust = 0.0
        self.max_trust = 1.0
        self.trust_range = self.max_trust - self.min_trust

    def _update_reputation(self, agent_id, action):
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        if action == 'cooperate':
            self.reputation[agent_id] = self.reputation[agent_id] * self.reputation_decay + (1 - self.reputation_decay)
        else:
            self.reputation[agent_id] = self.reputation[agent_id] * self.reputation_decay
        self.reputation[agent_id] = max(self.min_trust, min(self.max_trust, self.reputation[agent_id]))

    def _update_own_history(self, action):
        self.own_action_history.append(action)
        if action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

    def _update_observed_actions(self, donor_id, donor_action, recipient_id, recipient_action):
        key = (min(donor_id, recipient_id), max(donor_id, recipient_id))
        if key not in self.observed_actions:
            self.observed_actions[key] = []
        self.observed_actions[key].append((donor_id, donor_action, recipient_id, recipient_action))

    def _get_opponent_trust(self, opponent_id):
        if opponent_id in self.reputation:
            return self.reputation[opponent_id]
        return 0.5

    def _get_opponent_cooperation_rate(self, opponent_id):
        if opponent_id in self.opponent_history:
            actions = self.opponent_history[opponent_id]
            if actions:
                return sum(1 for a in actions if a == 'cooperate') / len(actions)
        return 0.5

    def _get_opponent_last_action(self, opponent_id):
        if opponent_id in self.opponent_history and self.opponent_history[opponent_id]:
            return self.opponent_history[opponent_id][-1]
        return None

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        trust = self._get_opponent_trust(opponent_id)
        coop_rate = self._get_opponent_cooperation_rate(opponent_id)
        last_action = self._get_opponent_last_action(opponent_id)

        # Compute cooperation probability based on trust, reputation, and reciprocity
        prob = self.base_cooperation_probability
        # Trust component
        prob += self.reputation_weight * (trust - 0.5) * 2
        # Reciprocity: if last action was cooperate, increase prob; if defect, decrease
        if last_action == 'cooperate':
            prob += self.reciprocity_factor * 0.2
        elif last_action == 'defect':
            prob -= self.reciprocity_factor * 0.3
        # Cooperation rate adjustment
        prob += (coop_rate - 0.5) * 0.2
        # Clamp between 0.05 and 0.95
        prob = max(0.05, min(0.95, prob))

        # Use deterministic pseudo-random based on round and opponent to avoid pure randomness
        seed = (self.agent_id * 1000 + opponent_id * 10 + self.round_num)
        random.seed(seed)
        decision = random.random() < prob
        return decision

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for both agents
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # Update observed actions
        self._update_observed_actions(donor_id, donor_action, recipient_id, recipient_action)

        # If this is self-judgment, record own action and opponent's action
        if donor_id == self.agent_id:
            self._update_own_history(donor_action)
            if recipient_id not in self.opponent_history:
                self.opponent_history[recipient_id] = []
            self.opponent_history[recipient_id].append(recipient_action)
        elif recipient_id == self.agent_id:
            self._update_own_history(recipient_action)
            if donor_id not in self.opponent_history:
                self.opponent_history[donor_id] = []
            self.opponent_history[donor_id].append(donor_action)
        else:
            # Third-party observation: could influence reputation but already done above
            pass

