        self.reputation = {}
        self.interaction_count = {}
        self.coop_rate = {}
        self.observation_count = {}
        self.opponent_history = {}
        self.generation = 0
        self.round_in_generation = 0
        self.total_rounds = 0
        self.self_actions = []
        self.self_rewards = []
        self.base_coop = 0.5

    def _get_rep(self, agent_id):
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _get_coop_rate(self, agent_id):
        if agent_id not in self.coop_rate:
            self.coop_rate[agent_id] = 0.5
        return self.coop_rate[agent_id]

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        opp_rep = self._get_rep(opponent)
        opp_coop = self._get_coop_rate(opponent)

        key = (min(self.agent_id, opponent), max(self.agent_id, opponent))
        if key in self.opponent_history:
            hist = self.opponent_history[key]
            mut_coop = hist.get('both_coop', 0)
            mut_def = hist.get('both_def', 0)
            i_coop_opp_def = hist.get('i_coop_opp_def', 0)
            i_def_opp_coop = hist.get('i_def_opp_coop', 0)
            total = mut_coop + mut_def + i_coop_opp_def + i_def_opp_coop
            if total > 0:
                trust = (mut_coop + i_def_opp_coop) / total
            else:
                trust = 0.5
        else:
            trust = 0.5

        combined = 0.6 * trust + 0.4 * opp_rep

        generation_factor = max(0.0, 1.0 - self.generation / 30.0)
        round_factor = 1.0 - (self.round_in_generation / 30.0) * 0.3
        threshold = 0.5 - generation_factor * 0.15 - (0.5 - self.base_coop)

        if combined < threshold:
            return False

        if key in self.opponent_history:
            hist = self.opponent_history[key]
            total = (hist.get('both_coop', 0) + hist.get('both_def', 0) +
                     hist.get('i_coop_opp_def', 0) + hist.get('i_def_opp_coop', 0))
            if total >= 3:
                opp_coop_against_us = (hist.get('both_coop', 0) + hist.get('i_def_opp_coop', 0)) / total
                if opp_coop_against_us < 0.25:
                    return False

        if self.total_rounds % 17 == 0 and (self.agent_id + self.total_rounds) % 5 == 0:
            return True

        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self.total_rounds += 1
        self.observation_count[donor_id] = self.observation_count.get(donor_id, 0) + 1
        self.observation_count[recipient_id] = self.observation_count.get(recipient_id, 0) + 1

        self._update_rep(donor_id, donor_action)
        self._update_rep(recipient_id, recipient_action)

        self._update_coop_rate(donor_id, donor_action)
        self._update_coop_rate(recipient_id, recipient_action)

        key = (min(donor_id, recipient_id), max(donor_id, recipient_id))
        if key not in self.opponent_history:
            self.opponent_history[key] = {'both_coop': 0, 'both_def': 0,
                                          'i_coop_opp_def': 0, 'i_def_opp_coop': 0}

        hist = self.opponent_history[key]
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
            else:
                my_action = recipient_action
                opp_action = donor_action

            self.self_actions.append(my_action)
            if my_action == 'cooperate' and opp_action == 'cooperate':
                reward = 3
            elif my_action == 'cooperate' and opp_action == 'defect':
                reward = 0
            elif my_action == 'defect' and opp_action == 'cooperate':
                reward = 5
            else:
                reward = 1
            self.self_rewards.append(reward)

            if my_action == 'cooperate' and opp_action == 'cooperate':
                hist['both_coop'] += 1
            elif my_action == 'defect' and opp_action == 'defect':
                hist['both_def'] += 1
            elif my_action == 'cooperate' and opp_action == 'defect':
                hist['i_coop_opp_def'] += 1
            else:
                hist['i_def_opp_coop'] += 1
        else:
            pass

        if len(self.self_rewards) >= 10:
            avg_reward = sum(self.self_rewards[-20:]) / max(1, len(self.self_rewards[-20:]))
            if avg_reward < 2.0:
                self.base_coop = max(0.3, self.base_coop - 0.01)
            elif avg_reward > 3.5:
                self.base_coop = min(0.9, self.base_coop + 0.01)

    def _update_rep(self, agent_id, action):
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + 0.04)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - 0.04)

    def _update_coop_rate(self, agent_id, action):
        if agent_id not in self.coop_rate:
            self.coop_rate[agent_id] = 0.5
        alpha = 0.1
        if action == 'cooperate':
            self.coop_rate[agent_id] = (1 - alpha) * self.coop_rate[agent_id] + alpha
        else:
            self.coop_rate[agent_id] = (1 - alpha) * self.coop_rate[agent_id]

