            my_opponent = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            opp_action = recipient_action if donor_id == self.agent_id else donor_action
            self._update_my_history(my_opponent, my_action, opp_action)

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        delta = 0.1 if action == 'cooperate' else -0.1
        self.reputation[agent_id] = min(1.0, max(0.0, self.reputation[agent_id] + delta))

    def _track_interaction(self, donor_id: int, recipient_id: int, donor_action: str, recipient_action: str) -> None:
