            if hist[-1][1] == 'defect':
                return False
            return random.random() < self.reputation[opponent]
        else:
            if self.global_total_count > 0:
                global_coop_rate = self.global_coop_count / self.global_total_count
                if global_coop_rate < 0.3:
                    return False
            return True

