                self.coop_count += 1
            else:
                self.defect_count += 1
            pass
        if recipient_id == self.agent_id:
            self.last_action_against_us[donor_id] = donor_action
            if donor_id not in self.interactions:
                self.interactions[donor_id] = 0
            pass

