class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_counts = {}
        self.defection_counts = {}
        self.total_actions = {}
        self.my_coop = 0
        self.my_defect = 0
        self.my_actions = []
        self.opponent_actions = []
        self.generation = 0
        self.rounds_in_generation = 0
        self.trust = {}
        self.epsilon = 0.05
        self.initial_trust = 0.5
        self.forgiveness = 0.02
        self.retaliation = 0.05

    def _safe_get(self, d, key, default):
        return d.get(key, default)

    def _update_reputation(self, agent_id, action, other_id=None):
        if action == 'cooperate':
            self.cooperation_counts[agent_id] = self.cooperation_counts.get(agent_id, 0) + 1
        else:
            self.defection_counts[agent_id] = self.defection_counts.get(agent_id, 0) + 1
        total = self.cooperation_counts.get(agent_id, 0) + self.defection_counts.get(agent_id, 0)
        self.total_actions[agent_id] = total
        if total > 0:
            self.reputation[agent_id] = self.cooperation_counts[agent_id] / total
        else:
            self.reputation[agent_id] = 0.5

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp not in self.trust:
            self.trust[opp] = self.initial_trust

        # Simple tit-for-tat with forgiveness and occasional exploration
        if self.my_actions and self.opponent_actions:
            last_opp = self.opponent_actions[-1]
            # If opponent defected last time, retaliate with some probability
            if last_opp == 'defect':
                if random.random() < self.retaliation:
                    return False
                else:
                    return True
            else:
                # If opponent cooperated, cooperate
                return True
        else:
            # First interaction: cooperate by default, but with small chance to test
            if random.random() < self.epsilon:
                return False
            else:
                return True

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        # Update reputation for both actors
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # If I am involved, update my personal history
        if donor_id == self.agent_id:
            self.my_actions.append(donor_action)
            self.opponent_actions.append(recipient_action)
            self._update_trust(recipient_id, donor_action, recipient_action)
        elif recipient_id == self.agent_id:
            self.my_actions.append(recipient_action)
            self.opponent_actions.append(donor_action)
            self._update_trust(donor_id, recipient_action, donor_action)

        # Update trust based on third-party observations (indirect reciprocity)
        else:
            # Update trust for donor based on action
            if donor_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, self.initial_trust) + self.forgiveness
            else:
                self.trust[donor_id] = self.trust.get(donor_id, self.initial_trust) - self.retaliation
            # Update trust for recipient based on action
            if recipient_action == 'cooperate':
                self.trust[recipient_id] = self.trust.get(recipient_id, self.initial_trust) + self.forgiveness
            else:
                self.trust[recipient_id] = self.trust.get(recipient_id, self.initial_trust) - self.retaliation

        # Clamp trust values
        for aid in self.trust:
            self.trust[aid] = max(0.0, min(1.0, self.trust[aid]))

    def _update_trust(self, other_id, my_action, opp_action):
        # Direct interaction updates trust
        if my_action == 'cooperate' and opp_action == 'cooperate':
            self.trust[other_id] = self.trust.get(other_id, self.initial_trust) + 0.1
        elif my_action == 'cooperate' and opp_action == 'defect':
            self.trust[other_id] = self.trust.get(other_id, self.initial_trust) - 0.2
        elif my_action == 'defect' and opp_action == 'cooperate':
            self.trust[other_id] = self.trust.get(other_id, self.initial_trust) + 0.05
        else:  # both defect
            self.trust[other_id] = self.trust.get(other_id, self.initial_trust) - 0.05
        # Clamp
        self.trust[other_id] = max(0.0, min(1.0, self.trust[other_id]))

