class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each other agent, count of cooperative and defective actions observed
        self.coop_count = {}
        self.defect_count = {}
        # Track outcomes with specific opponents
        self.interactions = {}  # opponent_id -> list of (my_action, their_action)
        # Generosity threshold: cooperate if opponent's cooperative ratio is high enough
        self.threshold = 0.5
        # Small memory: recent own actions to avoid being too predictable
        self.recent_actions = []
        # Randomness for exploration occasionally
        self.explore_prob = 0.05

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        # If no history with opponent, default to cooperate but with some caution
        if opponent_id not in self.coop_count and opponent_id not in self.defect_count:
            return True

        # Compute opponent's cooperative ratio
        coop = self.coop_count.get(opponent_id, 0)
        defect = self.defect_count.get(opponent_id, 0)
        total = coop + defect
        if total == 0:
            ratio = 0.5
        else:
            ratio = coop / total

        # Tit-for-tat with forgiveness: if opponent defected last time, defect unless they have been mostly cooperative
        if opponent_id in self.interactions and self.interactions[opponent_id]:
            last_their = self.interactions[opponent_id][-1][1]
            if last_their == 'defect' and ratio < 0.8:
                # Defect to punish, but with small chance to explore cooperation
                if random.random() < self.explore_prob:
                    return True
                return False

        # Otherwise cooperate if opponent's ratio is above threshold
        if ratio >= self.threshold:
            return True
        else:
            # Defect if opponent is not cooperative enough
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation counts for the donor
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
            else:
                self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1

        # Update reputation counts for the recipient
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
            else:
                self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

        # If this is a self-judgment (we are donor or recipient), record interaction
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine who is the opponent
            opponent_id = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            their_action = recipient_action if donor_id == self.agent_id else donor_action

            # Store interaction
            if opponent_id not in self.interactions:
                self.interactions[opponent_id] = []
            if len(self.interactions[opponent_id]) > 50:  # keep memory limited
                self.interactions[opponent_id].pop(0)
            self.interactions[opponent_id].append((my_action, their_action))

            # Update recent actions
            self.recent_actions.append(my_action)
            if len(self.recent_actions) > 10:
                self.recent_actions.pop(0)

            # Adapt threshold slightly based on own experience (simple learning)
            # If we've been exploited, increase threshold; if we've been cooperative and it paid off, decrease
            if len(self.interactions[opponent_id]) >= 3:
                recent_opponent = [x[1] for x in self.interactions[opponent_id][-3:]]
                if recent_opponent.count('defect') >= 2:
                    self.threshold = min(1.0, self.threshold + 0.05)
                elif recent_opponent.count('cooperate') >= 2:
                    self.threshold = max(0.0, self.threshold - 0.02)

