class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round_num = 0
        self.reputation = {}
        self.scores = {}
        self.interactions = {}
        self.my_choices = []
        self.opponent_choices = {}
        self.total_score = 0
        self.avg_coop_rate = 0.5
        self.generosity = 0.5
        self.forgiveness = 0.5
        self.trust_threshold = 0.4
        self.adaptation_rate = 0.1
        self.reputation_memory = {}
        self.strategy = "tit_for_tat"
        self.gen = 0
        self.last_opponent = None
        self.last_my_action = None
        self.last_opponent_action = None

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent

        # Update strategy based on performance and reputation
        if self.round_num > 0 and self.round_num % 10 == 0:
            self.update_strategy()

        # Determine action based on current strategy
        if self.strategy == "tit_for_tat":
            action = self.tit_for_tat(opponent)
        elif self.strategy == "generous_tit_for_tat":
            action = self.generous_tit_for_tat(opponent)
        elif self.strategy == "forgiving":
            action = self.forgiving_strategy(opponent)
        elif self.strategy == "trust_based":
            action = self.trust_based(opponent)
        else:
            action = self.cooperate_if_reputation_good(opponent)

        # Record my action
        action_bool = action
        self.last_my_action = action_bool
        self.my_choices.append(action_bool)

        self.round_num += 1
        return action_bool

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        # Update reputation for observed interactions
        donor_coop = 1 if donor_action == 'cooperate' else 0
        recipient_coop = 1 if recipient_action == 'cooperate' else 0

        # Update reputation based on action
        if donor_id != self.agent_id:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5)
            # Reward cooperation, punish defection
            if donor_coop == 1:
                self.reputation[donor_id] += 0.05
            else:
                self.reputation[donor_id] -= 0.1
            self.reputation[donor_id] = max(0, min(1, self.reputation[donor_id]))

        if recipient_id != self.agent_id:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5)
            if recipient_coop == 1:
                self.reputation[recipient_id] += 0.05
            else:
                self.reputation[recipient_id] -= 0.1
            self.reputation[recipient_id] = max(0, min(1, self.reputation[recipient_id]))

        # Record own interactions for learning
        if donor_id == self.agent_id:
            # I was donor
            opp = recipient_id
            self.interactions.setdefault(opp, []).append((donor_coop, recipient_coop))
            self.scores[opp] = self.scores.get(opp, 0)
            if donor_coop == 1 and recipient_coop == 1:
                self.scores[opp] += 3
            elif donor_coop == 1 and recipient_coop == 0:
                self.scores[opp] += 0
            elif donor_coop == 0 and recipient_coop == 1:
                self.scores[opp] += 5
            else:
                self.scores[opp] += 1
        elif recipient_id == self.agent_id:
            # I was recipient
            opp = donor_id
            self.interactions.setdefault(opp, []).append((donor_coop, recipient_coop))
            self.scores[opp] = self.scores.get(opp, 0)
            if donor_coop == 1 and recipient_coop == 1:
                self.scores[opp] += 3
            elif donor_coop == 1 and recipient_coop == 0:
                self.scores[opp] += 0
            elif donor_coop == 0 and recipient_coop == 1:
                self.scores[opp] += 5
            else:
                self.scores[opp] += 1

        # Update average cooperation rate for self
        if donor_id == self.agent_id:
            self.avg_coop_rate = (self.avg_coop_rate * (self.round_num - 1) + donor_coop) / max(1, self.round_num)

    def tit_for_tat(self, opponent):
        # Cooperate first time, then mirror opponent's last action
        if opponent not in self.interactions:
            return True
        last_interaction = self.interactions[opponent][-1]
        if self.agent_id == self._ctx_opponent_id:  # shouldn't happen but safe
            return True
        # Determine opponent's last action as donor or recipient
        if last_interaction[0] == 1 and last_interaction[1] == 1:
            return True
        elif last_interaction[0] == 0 or last_interaction[1] == 0:
            # If opponent defected at all, defect
            return False
        return True

    def generous_tit_for_tat(self, opponent):
        # TFT with forgiveness probability
        if opponent not in self.interactions:
            return True
        last_interaction = self.interactions[opponent][-1]
        opp_defected = (last_interaction[0] == 0 or last_interaction[1] == 0)
        if opp_defected:
            # Forgive with probability based on forgiveness
            if random.random() < self.forgiveness:
                return True
            else:
                return False
        return True

    def forgiving_strategy(self, opponent):
        # Cooperate unless opponent has defected many times recently
        if opponent not in self.interactions:
            return True
        recent = self.interactions[opponent][-5:]
        defections = sum(1 for (d, r) in recent if d == 0 or r == 0)
        if defections >= 3:
            return False
        return True

    def trust_based(self, opponent):
        # Use reputation to decide
        rep = self.reputation.get(opponent, 0.5)
        if rep > self.trust_threshold:
            return True
        else:
            return False

    def cooperate_if_reputation_good(self, opponent):
        rep = self.reputation.get(opponent, 0.5)
        return rep > 0.4

    def update_strategy(self):
        # Choose best strategy based on recent performance
        # Simple heuristic: switch to more cooperative if doing well
        recent_scores = list(self.scores.values())[-10:] if self.scores else []
        if recent_scores:
            avg_score = sum(recent_scores) / len(recent_scores)
            if avg_score < 2.0:
                # Doing poorly, try more aggressive
                self.strategy = "tit_for_tat"
                self.forgiveness = 0.2
            elif avg_score > 3.5:
                # Doing well, be more generous
                self.strategy = "generous_tit_for_tat"
                self.forgiveness = 0.6
            else:
                # Moderate, use trust-based
                self.strategy = "trust_based"
        # Adjust trust threshold based on overall cooperation
        if self.avg_coop_rate < 0.3:
            self.trust_threshold = 0.5
        else:
            self.trust_threshold = 0.4

