class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputation = {}
        self.own_history = []
        self.interactions = {}
        self.coop_rate = {}
        self.recent_actions = {}
        self.forget = 0.9
        self.base_threshold = 0.5
        self.threshold = self.base_threshold
        self.own_coop_count = 0
        self.own_total = 0
        self.exploited_count = 0
        self.recent_outcomes = []
        self.generosity = 0.1

    def _init_agent_state(self, agent_id: int) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        if agent_id not in self.interactions:
            self.interactions[agent_id] = 0
        if agent_id not in self.coop_rate:
            self.coop_rate[agent_id] = 0.5
        if agent_id not in self.recent_actions:
            self.recent_actions[agent_id] = []

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True
        opp = self._ctx_opponent_id
        self._init_agent_state(opp)
        if self.recent_outcomes:
            avg = sum(self.recent_outcomes) / len(self.recent_outcomes)
            self.threshold = self.base_threshold - avg * 0.1
        else:
            self.threshold = self.base_threshold
        rep = self.reputation[opp]
        if opp in self.interactions and self.interactions[opp] > 0:
            my_coop_count = 0
            opp_coop_count = 0
            for _, my_action, opp_action in self.own_history:
                if _ == opp:
                    if my_action == 'cooperate':
                        my_coop_count += 1
                    if opp_action == 'cooperate':
                        opp_coop_count += 1
            if self.interactions[opp] > 0:
                opp_coop_rate = opp_coop_count / self.interactions[opp]
            else:
                opp_coop_rate = 0.5
            rep = 0.7 * rep + 0.3 * opp_coop_rate
        p = 1.0 / (1.0 + math.exp(-10 * (rep - self.threshold)))
        p = p * 0.9 + 0.05
        return random.random() < p

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self._init_agent_state(donor_id)
        self._init_agent_state(recipient_id)
        delta = 0.1
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation[donor_id] + (1 - self.reputation[donor_id]) * delta
        else:
            self.reputation[donor_id] = self.reputation[donor_id] - self.reputation[donor_id] * delta
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation[recipient_id] + (1 - self.reputation[recipient_id]) * delta
        else:
            self.reputation[recipient_id] = self.reputation[recipient_id] - self.reputation[recipient_id] * delta
        if donor_id in self.recent_actions:
            self.recent_actions[donor_id].append(donor_action)
            if len(self.recent_actions[donor_id]) > 5:
                self.recent_actions[donor_id].pop(0)
        if recipient_id in self.recent_actions:
            self.recent_actions[recipient_id].append(recipient_action)
            if len(self.recent_actions[recipient_id]) > 5:
                self.recent_actions[recipient_id].pop(0)
        for aid, act in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if aid in self.coop_rate:
                self.coop_rate[aid] = self.forget * self.coop_rate[aid] + (1 - self.forget) * (1 if act == 'cooperate' else 0)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id
            self.own_history.append((opp_id, my_action, opp_action))
            self.interactions[opp_id] = self.interactions.get(opp_id, 0) + 1
            self.own_total += 1
            if my_action == 'cooperate':
                self.own_coop_count += 1
            if my_action == 'cooperate' and opp_action == 'cooperate':
                outcome = 1
            elif my_action == 'defect' and opp_action == 'defect':
                outcome = -1
            elif my_action == 'cooperate' and opp_action == 'defect':
                outcome = -1
                self.exploited_count += 1
            elif my_action == 'defect' and opp_action == 'cooperate':
                outcome = 0
            self.recent_outcomes.append(outcome)
            if len(self.recent_outcomes) > 10:
                self.recent_outcomes.pop(0)
            if self.exploited_count > 5:
                self.base_threshold = 0.6
            elif self.exploited_count > 2:
                self.base_threshold = 0.55
            else:
                self.base_threshold = 0.5

