class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation for each other agent: 0 unknown, positive good, negative bad
        self.reputation = {}
        # Track how many times each agent defected/cooperated overall
        self.coop_count = {}
        self.defect_count = {}
        # Track interactions with each opponent: list of (my_action, opp_action)
        self.interactions = {}
        # Track my own recent actions for potential retaliation strategy
        self.my_recent_actions = []
        # Track opponent's recent actions per opponent
        self.opp_recent = {}
        # Track last observed actions for each pair to detect patterns
        self.pair_history = {}
        # Generosity factor - how forgiving we are
        self.generosity = 0.1
        # Baseline cooperation probability when no info
        self.base_coop = 0.6
        # Track rounds played
        self.rounds_played = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # shouldn't happen, but be safe

        # If we have no history with this opponent, use base probability
        if opponent not in self.interactions:
            # Check reputation from observations
            if opponent in self.reputation:
                rep = self.reputation[opponent]
                # If reputation is bad, lower cooperation chance
                if rep < -2:
                    return False
                elif rep > 2:
                    return True
            return random.random() < self.base_coop

        # Get recent interaction history
        history = self.interactions.get(opponent, [])
        if not history:
            return random.random() < self.base_coop

        # Compute opponent's cooperation rate
        coop_rate = sum(1 for my, opp in history if opp == 'cooperate') / len(history)

        # If opponent has defected recently, retaliate
        recent_opp_actions = self.opp_recent.get(opponent, [])
        if recent_opp_actions and recent_opp_actions[-1] == 'defect':
            # Tit-for-tat with some forgiveness
            if random.random() > self.generosity:
                return False

        # If opponent cooperates most of the time, cooperate
        if coop_rate > 0.7:
            return True
        elif coop_rate < 0.3:
            return False
        else:
            # Mixed: cooperate with probability based on their rate
            return random.random() < coop_rate

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation based on observed actions
        # For donor: cooperating is good, defecting is bad
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) + 1
                self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 1
                self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1

        # For recipient: receiving cooperation is neutral, but if they defect while being recipient? 
        # Actually recipient's action is what they chose, so same logic
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + 1
                self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
            else:
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) - 1
                self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

        # If this involves us directly, record our interaction
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            # Store interaction
            if opp_id not in self.interactions:
                self.interactions[opp_id] = []
            self.interactions[opp_id].append((my_action, opp_action))
            # Keep only last 50 interactions for memory
            if len(self.interactions[opp_id]) > 50:
                self.interactions[opp_id] = self.interactions[opp_id][-50:]

            # Track recent actions
            if opp_id not in self.opp_recent:
                self.opp_recent[opp_id] = []
            self.opp_recent[opp_id].append(opp_action)
            if len(self.opp_recent[opp_id]) > 10:
                self.opp_recent[opp_id] = self.opp_recent[opp_id][-10:]

            self.my_recent_actions.append(my_action)
            if len(self.my_recent_actions) > 10:
                self.my_recent_actions = self.my_recent_actions[-10:]

            self.rounds_played += 1

        # Track pair history for pattern detection
        pair_key = (donor_id, recipient_id)
        if pair_key not in self.pair_history:
            self.pair_history[pair_key] = []
        self.pair_history[pair_key].append((donor_action, recipient_action))
        if len(self.pair_history[pair_key]) > 20:
            self.pair_history[pair_key] = self.pair_history[pair_key][-20:]

