        # Cooperate first time, then mirror opponent's last action
        if opponent not in self.interactions:
            return True
        last_interaction = self.interactions[opponent][-1]
        if self.agent_id == self._ctx_opponent_id:  # shouldn't happen but safe
            return True
        # Determine opponent's last action as donor or recipient
        if last_interaction[0] == 1 and last_interaction[1] == 1:
            return True
        elif last_interaction[0] == 0 or last_interaction[1] == 0:
            # If opponent defected at all, defect
            return False
        return True

    def generous_tit_for_tat(self, opponent):
        # TFT with forgiveness probability
        if opponent not in self.interactions:
            return True
        last_interaction = self.interactions[opponent][-1]
        opp_defected = (last_interaction[0] == 0 or last_interaction[1] == 0)
        if opp_defected:
            # Forgive with probability based on forgiveness
            if random.random() < self.forgiveness:
                return True
            else:
                return False
        return True

    def forgiving_strategy(self, opponent):
        # Cooperate unless opponent has defected many times recently
        if opponent not in self.interactions:
            return True
        recent = self.interactions[opponent][-5:]
        defections = sum(1 for (d, r) in recent if d == 0 or r == 0)
        if defections >= 3:
            return False
        return True

    def trust_based(self, opponent):
        # Use reputation to decide
        rep = self.reputation.get(opponent, 0.5)
        if rep > self.trust_threshold:
            return True
        else:
            return False

    def cooperate_if_reputation_good(self, opponent):
        rep = self.reputation.get(opponent, 0.5)
        return rep > 0.4

    def update_strategy(self):
        # Choose best strategy based on recent performance
        # Simple heuristic: switch to more cooperative if doing well
        recent_scores = list(self.scores.values())[-10:] if self.scores else []
        if recent_scores:
            avg_score = sum(recent_scores) / len(recent_scores)
            if avg_score < 2.0:
                # Doing poorly, try more aggressive
                self.strategy = "tit_for_tat"
                self.forgiveness = 0.2
            elif avg_score > 3.5:
                # Doing well, be more generous
                self.strategy = "generous_tit_for_tat"
                self.forgiveness = 0.6
            else:
                # Moderate, use trust-based
                self.strategy = "trust_based"
        # Adjust trust threshold based on overall cooperation
        if self.avg_coop_rate < 0.3:
            self.trust_threshold = 0.5
        else:
            self.trust_threshold = 0.4

