            prob = base - 0.3 * (self.trust_threshold - opp_coop_rate) / self.trust_threshold

        prob = max(0.0, min(1.0, prob))

        return random.random() < prob + 0.04

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        is_self = (donor_id == self.agent_id) or (recipient_id == self.agent_id)

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                if agent_id not in self.reputation:
                    self.reputation[agent_id] = [0, 0]
                if action == 'cooperate':
                    self.reputation[agent_id][0] += 1
                else:
                    self.reputation[agent_id][1] += 1
                if not is_self:
                    self.others_total_obs += 1
                    if action == 'cooperate':
                        self.others_coop_obs += 1

        if donor_id == self.agent_id:
            self.own_coop_count += 1 if donor_action == 'cooperate' else 0
            self.own_defect_count += 1 if donor_action == 'defect' else 0
            my_action = (donor_action == 'cooperate')
            self.recent_actions.append(my_action)
            if len(self.recent_actions) > self.recent_window:
                self.recent_actions.pop(0)
            opp_id = recipient_id
            opp_action = (recipient_action == 'cooperate')
            if opp_id not in self.direct_opponent_recent:
                self.direct_opponent_recent[opp_id] = []
            self.direct_opponent_recent[opp_id].append(opp_action)
            if len(self.direct_opponent_recent[opp_id]) > 10:
                self.direct_opponent_recent[opp_id].pop(0)
        elif recipient_id == self.agent_id:
            self.own_coop_count += 1 if recipient_action == 'cooperate' else 0
            self.own_defect_count += 1 if recipient_action == 'defect' else 0
            my_action = (recipient_action == 'cooperate')
            self.recent_actions.append(my_action)
            if len(self.recent_actions) > self.recent_window:
                self.recent_actions.pop(0)
            opp_id = donor_id
            opp_action = (donor_action == 'cooperate')
            if opp_id not in self.direct_opponent_recent:
                self.direct_opponent_recent[opp_id] = []
            self.direct_opponent_recent[opp_id].append(opp_action)
            if len(self.direct_opponent_recent[opp_id]) > 10:
                self.direct_opponent_recent[opp_id].pop(0)

        if self.others_total_obs > 0:
            self.others_coop_rate = self.others_coop_obs / self.others_total_obs

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_count = {}
        self.total_actions = {}
        self.interaction_history = {}
        self.has_interacted = set()
        self.round_count = 0
        self.generation_length = 30
        self.forgiveness_threshold = 0.6
        self.last_opponent_action = {}
        self.last_my_action = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent not in self.coop_count:
            self.coop_count[opponent] = 0
            self.total_actions[opponent] = 0
        if opponent not in self.has_interacted:
            return True
        if self.total_actions[opponent] > 0:
            rep = self.coop_count[opponent] / self.total_actions[opponent]
        else:
            rep = 0.5
        my_last = self.last_my_action.get(opponent, None)
        opp_last = self.last_opponent_action.get(opponent, None)
        if opp_last == "cooperate":
            return True
        elif opp_last == "defect":
            if rep >= self.forgiveness_threshold:
                return True
            else:
                return False
        else:
            return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.coop_count:
                self.coop_count[agent_id] = 0
                self.total_actions[agent_id] = 0
            if action == "cooperate":
                self.coop_count[agent_id] += 1
            self.total_actions[agent_id] += 1

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = donor_id if donor_id != self.agent_id else recipient_id
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
            else:
                my_action = recipient_action
                opp_action = donor_action
            self.interaction_history.setdefault(other_id, []).append((my_action, opp_action))
            self.has_interacted.add(other_id)
            self.last_my_action[other_id] = my_action
            self.last_opponent_action[other_id] = opp_action
            self.round_count += 1
            generation = self.round_count // self.generation_length
            if generation >= 5:
                self.forgiveness_threshold = 0.4
            elif generation >= 10:
                self.forgiveness_threshold = 0.35
            elif generation >= 15:
                self.forgiveness_threshold = 0.3
